#include <iostream>
#include <vector>
#include <queue>
using namespace std;

vector<int> kahnTopSort(vector<vector<int>>& adj, int V) {
    vector<int> inDegree(V, 0);

    // Step 1: compute in-degree of every node
    for (int u = 0; u < V; u++)
        for (int v : adj[u])
            inDegree[v]++;

    // Step 2: enqueue all nodes with in-degree 0
    queue<int> q;
    for (int i = 0; i < V; i++)
        if (inDegree[i] == 0)
            q.push(i);

    vector<int> result;

    while (!q.empty()) {
        int node = q.front();
        q.pop();

        result.push_back(node); // Step 3: add to result

        for (int neighbour : adj[node]) {
            inDegree[neighbour]--; // Step 4: remove edge

            if (inDegree[neighbour] == 0)
                q.push(neighbour); // Step 5: now ready
        }
    }

    // Step 6: cycle check
    if (result.size() != V) {
        throw runtime_error("Graph has a cycle — no topological order");
    }

    return result;
}

int main() {
    int V = 6;
    vector<vector<int>> adj(V);

    // Example DAG
    adj[5].push_back(2);
    adj[5].push_back(0);
    adj[4].push_back(0);
    adj[4].push_back(1);
    adj[2].push_back(3);
    adj[3].push_back(1);

    vector<int> order = kahnTopSort(adj, V);

    for (int node : order)
        cout << node << " ";
}

#include <iostream>
#include <vector>
#include <stack>
using namespace std;

class Graph {
private:
    int V;
    vector<vector<int>> adj;
    stack<int> st;
    vector<bool> visited;

public:
    Graph(int v) {
        V = v;
        adj.resize(V);
        visited.resize(V, false);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v); // directed edge
    }

    void dfs(int node) {
        visited[node] = true;

        for (int neighbour : adj[node]) {
            if (!visited[neighbour])
                dfs(neighbour);
        }

        st.push(node); // push AFTER exploring all neighbours
    }

    vector<int> topoSortDFS() {
        for (int i = 0; i < V; i++) {
            if (!visited[i])
                dfs(i);
        }

        vector<int> result;

        while (!st.empty()) {
            result.push_back(st.top()); // pop = reverse finish order
            st.pop();
        }

        return result;
    }
};

int main() {
    Graph g(6);

    g.addEdge(5,2);
    g.addEdge(5,0);
    g.addEdge(4,0);
    g.addEdge(4,1);
    g.addEdge(2,3);
    g.addEdge(3,1);

    vector<int> order = g.topoSortDFS();

    for (int node : order)
        cout << node << " ";
}
